# Generated by tools/codegen/gen_controller.py from controllers/esp32-t12-controller/controller.toml. Do not edit; change the description and regenerate.
# The CI steps of this controller after the common ones (.github/workflows/controllers.yml):
# its [hil] firmware and its [[ci.step]]s. Needs gcc, PlatformIO and tools/requirements.txt.
#
#   bash controllers/esp32-t12-controller/tools/ci.sh
#
# Exit status: 0 ok, 1 a step failed, 2 usage.
set -euo pipefail

usage() { sed -n '2,7p' "$0" | sed 's/^# \{0,1\}//'; exit "${1:-2}"; }
case ${1:-} in
  -h | --help) usage 0 ;;
  "") ;;
  *) usage ;;
esac
cd "$(dirname "$0")/.."

echo "== Build firmware on the HIL link"
pio run -e esp32dev-hil

echo "== Serial tools self-check"
python ../../tools/serial/capture.py --selftest
python ../../tools/serial/timing_check.py --selftest

echo "== Scenario CSVs, plots and tables"
mkdir -p .pio out
lib="lib/t12ctrl/src"
core="../../libs/ctrlcore/src"
plant="../../libs/plants/t12"
gcc -Ilib/t12ctrl/include -I../../libs/ctrlcore/include -I$plant/include \
  tools/scenarios.c $lib/t12_scenario.c $lib/t12_loop.c $lib/t12_ctrl.c $lib/t12_cycle.c \
  $lib/t12_convert.c $lib/t12_safety.c $lib/t12_io_sim.c $lib/t12_frontend.c \
  $core/pid.c $core/step_metrics.c \
  $plant/src/t12_plant.c -lm -o .pio/scenarios
for s in cold load ambient open short stuck runaway; do
  .pio/scenarios $s > out/scenario_$s.csv
  python tools/plot.py out/scenario_$s.csv out/scenario_$s.png
done
.pio/scenarios summary > out/scenarios.md
.pio/scenarios sweep > out/gain_sweep.md
